#include <cstdint>

// Simulating the header context
const uint32_t TABLE_SIZE = 262144;
struct glm { struct ivec3 { int x, y, z; }; };

// The implementation to test
uint32_t getHash(const glm::ivec3 &cell) {
    return (
        (uint32_t)(cell.x * 73856093)
        ^ (uint32_t)(cell.y * 19349663)
        ^ (uint32_t)(cell.z * 83492791)
    ) % TABLE_SIZE;
}

// Test
int main() {
    glm::ivec3 cell = {1, 2, 3};
    uint32_t h = getHash(cell);
    return h < TABLE_SIZE ? 0 : 1;
}

